import pickle
from pathlib import Path
import numpy as np
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score, roc_auc_score, confusion_matrix

PROJECT_ROOT = Path(__file__).resolve().parent.parent

def train_meta_learner():
    models_dir = PROJECT_ROOT / "models"
    
    # Load the 5-Fold OOF matrices generated by Layer 1
    oof_path = models_dir / "oof_layer1_data.pkl"
    if not oof_path.exists():
        raise FileNotFoundError(f"Could not find {oof_path}. Run train_layer1_oof.py first.")
        
    with open(oof_path, "rb") as f:
        oof_data = pickle.load(f)
        
    X_train_meta = oof_data["oof_train_probs"]
    y_train = oof_data["y_train"]
    X_test_meta = oof_data["oof_test_probs"]
    y_test = oof_data["y_test"]
    learner_names = oof_data["learner_names"]
    
    print("=" * 70)
    print("🧠 MEMBER 3: LAYER 2 META-LEARNER (Logistic Regression)")
    print("=" * 70)
    
    print(f"[*] Training Meta-Learner on Layer 1 Probabilities from: {learner_names}")
    
    # Train the Layer 2 Meta-Learner
    meta_model = LogisticRegression(class_weight="balanced", random_state=42, max_iter=1000)
    meta_model.fit(X_train_meta, y_train)
    
    # Predict on the unseen Holdout Test Set (20% of original data)
    test_probs = meta_model.predict_proba(X_test_meta)[:, 1]
    test_preds = (test_probs >= 0.5).astype(int)
    
    # Calculate Final Evaluation Metrics (Defect Class = 0)
    acc = accuracy_score(y_test, test_preds)
    prec = precision_score(y_test, test_preds, pos_label=0)
    rec = recall_score(y_test, test_preds, pos_label=0)
    f1 = f1_score(y_test, test_preds, pos_label=0)
    roc = roc_auc_score(y_test, test_probs)
    cm = confusion_matrix(y_test, test_preds)
    
    print("\n📊 FINAL 2-TIER ENSEMBLE PERFORMANCE (Unseen Holdout Set)")
    print("-" * 50)
    print(f"Accuracy         : {acc:.4f}")
    print(f"Defect Precision : {prec:.4f} (When it flags a defect, it is right {prec*100:.1f}% of the time)")
    print(f"Defect Recall    : {rec:.4f} (It successfully caught {rec*100:.1f}% of all actual defects)")
    print(f"Defect F1-Score  : {f1:.4f}")
    print(f"ROC-AUC          : {roc:.4f}")
    
    print("\n[Confusion Matrix]")
    print(f"True Defects Caught (TN)     : {cm[0][0]}")
    print(f"False Defect Alarms (FP)     : {cm[0][1]}")
    print(f"Missed Defects (FN)          : {cm[1][0]}")
    print(f"True Positives Detected (TP) : {cm[1][1]}")
    
    # Save the Meta-Learner for the Streamlit UI
    with open(models_dir / "layer2_meta_model.pkl", "wb") as f:
        pickle.dump(meta_model, f)
        
    print(f"\n[+] Saved Layer 2 Meta-Learner -> {models_dir / 'layer2_meta_model.pkl'}")

if __name__ == "__main__":
    train_meta_learner()